CREATE TABLE IF NOT EXISTS users (name TEXT PRIMARY KEY, role TEXT NOT NULL, pin TEXT NOT NULL DEFAULT '', color TEXT NOT NULL DEFAULT '', ord INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS types (name TEXT PRIMARY KEY, grp TEXT NOT NULL DEFAULT 'Papilddarbs', ord INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS objects (anorm TEXT PRIMARY KEY, adrese TEXT NOT NULL, vaditajs TEXT NOT NULL DEFAULT '', grupa TEXT NOT NULL DEFAULT 'SH objekti', piekluve TEXT NOT NULL DEFAULT '', ord INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS staff (name TEXT PRIMARY KEY, brigade TEXT NOT NULL DEFAULT '', ord INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS crew (id INTEGER PRIMARY KEY AUTOINCREMENT, datums TEXT NOT NULL, name TEXT NOT NULL, persons TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS crew_d ON crew(datums);
CREATE TABLE IF NOT EXISTS tokens (token TEXT PRIMARY KEY, name TEXT NOT NULL, device TEXT NOT NULL DEFAULT '', updated TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS jobs (
  id TEXT PRIMARY KEY, datums TEXT NOT NULL, adrese TEXT NOT NULL, anorm TEXT NOT NULL DEFAULT '', tips TEXT NOT NULL DEFAULT '', apraksts TEXT NOT NULL DEFAULT '',
  vaditajs TEXT NOT NULL DEFAULT '', brigade TEXT NOT NULL DEFAULT '', statuss TEXT NOT NULL DEFAULT 'jauns', publicets TEXT NOT NULL DEFAULT '', izpildits TEXT NOT NULL DEFAULT '',
  izveidots TEXT NOT NULL DEFAULT '', komentars TEXT NOT NULL DEFAULT '', foto TEXT NOT NULL DEFAULT '', iemesls TEXT NOT NULL DEFAULT '', lidz TEXT NOT NULL DEFAULT '',
  serija TEXT NOT NULL DEFAULT '', prombutne TEXT NOT NULL DEFAULT '', steidzami TEXT NOT NULL DEFAULT '', laiks TEXT NOT NULL DEFAULT '', parbaude TEXT NOT NULL DEFAULT '', parbKom TEXT NOT NULL DEFAULT '',
  seq INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS jobs_d ON jobs(datums);
CREATE INDEX IF NOT EXISTS jobs_s ON jobs(serija);
CREATE INDEX IF NOT EXISTS jobs_a ON jobs(anorm);
CREATE TABLE IF NOT EXISTS problems (id TEXT PRIMARY KEY, laiks TEXT NOT NULL DEFAULT '', adrese TEXT NOT NULL DEFAULT '', anorm TEXT NOT NULL DEFAULT '', vaditajs TEXT NOT NULL DEFAULT '', vieniba TEXT NOT NULL DEFAULT '',
  apraksts TEXT NOT NULL DEFAULT '', foto TEXT NOT NULL DEFAULT '', statuss TEXT NOT NULL DEFAULT 'jauns', atrisinats TEXT NOT NULL DEFAULT '', seq INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS standing (id TEXT PRIMARY KEY, adrese TEXT NOT NULL, tips TEXT NOT NULL DEFAULT '', apraksts TEXT NOT NULL DEFAULT '', vaditajs TEXT NOT NULL DEFAULT '', prombutne TEXT NOT NULL DEFAULT '',
  no TEXT NOT NULL DEFAULT '', beigas TEXT NOT NULL DEFAULT '', brivdienas TEXT NOT NULL DEFAULT '', steidzami TEXT NOT NULL DEFAULT '', laiks TEXT NOT NULL DEFAULT '', foto TEXT NOT NULL DEFAULT '',
  izlaistas TEXT NOT NULL DEFAULT '', izveidots TEXT NOT NULL DEFAULT '', seq INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS kv (k TEXT PRIMARY KEY, v TEXT NOT NULL DEFAULT '');
